public void paint(Graphics g){

    // Extract x and y coordinates from pointValues
    int x = pointValues.x;
    int y = pointValues.y;

    // Add x and y coordinates as separate elements to the ArrayList
    pointStorer.add(x);
    pointStorer.add(y);

    System.out.println("Index point "+pointStorer.indexOf(pointValues)); // This should now give you the correct index

}
```

